module freq_div_even(
    input clk, rst_n,
    output clk_div
);
    parameter NUM_DIV = 4'd6;
    reg [3:0] cnt;
    reg clk_div_reg;

    always@(posedge clk or negedge rst_n)begin
        if(!rst_n)begin
            cnt <= 4'd0;
            clk_div_reg <= 1'b0;
        end
        else if(cnt < ((NUM_DIV >> 1)-1))begin
            cnt <= cnt + 1'b1;
        end
        else begin
            cnt <= 4'd0;
            clk_div_reg <= ~clk_div_reg;
        end

    end

    assign clk_div = clk_div_reg;
endmodule
